// --- 150疾患＆DRUG_DIFF_MAP 完全網羅マルチサブタイプ拡張 ---
function createMultiSubtypeEntry(key, name, category, aliases, subtypes) {
  const q1Options = subtypes.map((st, idx) => {
    const weights = {};
    subtypes.forEach((other, oIdx) => {
      weights[other[0]] = (oIdx === idx) ? 95 : -20;
    });
    return {
      id: `${key}_q1_opt_${idx + 1}`,
      label: st[5],
      badge: st[4],
      desc: st[6],
      weights
    };
  });

  const q2Options = subtypes.map((st, idx) => {
    const weights = {};
    subtypes.forEach((other, oIdx) => {
      weights[other[0]] = (oIdx === idx) ? 98 : -20;
    });
    return {
      id: `${key}_q2_opt_${idx + 1}`,
      label: st[7],
      badge: st[4],
      desc: st[8],
      weights
    };
  });

  const diseases = subtypes.map((st, idx) => {
    const rawType = st[9] || 'guideline';
    const normType = rawType === 'off_label' ? 'offlabel' : rawType;
    const rawEv = st[10] || 'high';
    const normEv = rawEv === 'high' ? 'A' : (rawEv === 'medium' ? 'B' : (rawEv === 'low' ? 'C' : rawEv));
    const rawFreq = st[11] || 'common';
    const normFreq = rawFreq === 'uncommon' ? 'occasional' : rawFreq;
    const bp = st[13] ? Math.round(st[13] * 100) : Math.round(100 / subtypes.length);
    return {
      id: st[0],
      cardNum: typeof st[1] === 'number' ? st[1] : (idx + 1),
      name: st[2],
      subType: st[3],
      type: normType,
      evidence: normEv,
      frequency: normFreq,
      redFlag: Boolean(st[12]),
      sources: ['PMDA_PACKAGE_INSERT'],
      baseProb: bp,
      criteria: `【処方・鑑別サイン】：${st[5]}`,
      reason: st[6],
      keyPoint: st[8],
      treatment: {
        pathology: st[6],
        rationale: `【病態・薬理根拠】：${st[6]}`,
        firstLine: st[3],
        combination: st[5],
        contra: st[12] ? '禁忌・重大な副作用リスク（Red Flag）の確認が必須。' : '腎機能・肝機能・併用薬・アレルギー歴に応じた用量・用法の確認。',
        targets: st[2] + 'の症状寛解と再発・合併症予防',
        guidance: `🗣️ 服薬指導ポイント：${st[8]}`
      }
    };
  });

  return {
    name,
    category,
    aliases,
    questions: [
      {
        id: `${key}_q1_regimen`,
        title: `Q1. 【${name.split('（')[0]}】処方パターン・併用薬・用法の特徴はどれですか？`,
        subtitle: '処方構成・用量・剤形・併用薬から病態サブタイプを絞り込みます',
        options: q1Options
      },
      {
        id: `${key}_q2_clinical`,
        title: `Q2. 🗣️【患者確認・臨床背景】症状や治療目的・管理状況はどれに該当しますか？`,
        subtitle: '臨床症状と服薬指導上の重要確認ポイントからサブタイプを最終確定します',
        options: q2Options
      }
    ],
    diseases
  };
}

